import{_ as e,o as t,c as o,aw as r}from"./chunks/framework.DLufY-ao.js";const h=JSON.parse('{"title":"Вопросы","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/framework-react/redux-saga/common/questions.md","filePath":"wiki/dev-commit/framework-react/redux-saga/common/questions.md"}'),i={name:"wiki/dev-commit/framework-react/redux-saga/common/questions.md"};function s(l,a,n,c,d,m){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="вопросы" tabindex="-1">Вопросы <a class="header-anchor" href="#вопросы" aria-label="Permalink to &quot;Вопросы&quot;">​</a></h1><h2 id="почему-redux-saga-использует-генераторы-а-не-async-await" tabindex="-1">Почему redux saga использует генераторы, а не async await <a class="header-anchor" href="#почему-redux-saga-использует-генераторы-а-не-async-await" aria-label="Permalink to &quot;Почему redux saga использует генераторы, а не async await&quot;">​</a></h2><h3 id="ответ-от-chatgpt" tabindex="-1">Ответ от ChatGPT <a class="header-anchor" href="#ответ-от-chatgpt" aria-label="Permalink to &quot;Ответ от ChatGPT&quot;">​</a></h3><ol><li>Управление потоком: Генераторы предоставляют более гибкий и контролируемый способ управления потоком выполнения. Redux Saga позволяет паузить, возобновлять и отменять выполнение саги, что делает его мощным инструментом для сложных сценариев управления потоком данных</li><li>Параллельное выполнение: Генераторы позволяют легко создавать параллельные задачи и координировать их выполнение. Саги могут запускать несколько веток выполнения и ждать, пока все они завершатся</li><li>Отмена задач: Redux Saga обеспечивает механизм отмены выполнения саги, что может быть сложнее с асинхронными функциями. Это полезно, например, когда пользователь выполняет действие, которое требует отмены предыдущих запросов или задач</li></ol><h3 id="ответ-из-google" tabindex="-1">Ответ из Google <a class="header-anchor" href="#ответ-из-google" aria-label="Permalink to &quot;Ответ из Google&quot;">​</a></h3><ul><li>redux-saga нельзя переписать на async / await - в нем используются обещания и сложнее координировать с ними «параллельные» задачи. Это также означало бы большие изменения в семантике, в том, как все работает на самом деле. В примере эффект выбора синхронный - этого нельзя добиться с помощью обещаний.</li><li>Сага, являясь интерпретатором эффектов, дает нам полный контроль над тем, как и когда эти эффекты разрешаются + эффекты - это просто простой объект, который легко сопоставить и можно отслеживать, что также намного сложнее с Promises.</li></ul>',6)])])}const _=e(i,[["render",s]]);export{h as __pageData,_ as default};
